
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbeint_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbeint", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.030867132701338e-02, -6.927946883539710e-02, -6.780239364881760e-02, -6.568454558400660e-02, -6.265235030722123e-02, -5.832233121902286e-02, -5.217496802693308e-02, -4.358803197797242e-02, -3.220965372429455e-02, -1.973503336225266e-02, -1.456710617899541e-02, -4.135730558101440e-02, -4.795613777940998e-02, -3.503355111740552e-02, -1.909696616324952e-02, -5.152885394246237e-03, -3.199406572504611e-04, -3.020369402645516e-06, -3.114102678760049e-09, -1.232755270323975e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


